import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;
type CLVariant = 'infonce' | 'nt-xent' | 'triplet';

const W = 1400;
const CX = W / 2;
const BOX_H = 100;
const STEP_GAP = 960;
const BOX_TO_ROW = 480;
const FOOTER_PAD = 70;

const C = {
  embed:   { fill: '#e3f2fd', stroke: '#1565c0' },
  sim:     { fill: '#e8f5e9', stroke: '#2e7d32' },
  softmax: { fill: '#fff3e0', stroke: '#e65100' },
  loss:    { fill: '#ffebee', stroke: '#c62828' },
  triplet: { fill: '#f3e5f5', stroke: '#6a1b9a' },
  header:  { fill: '#e3f2fd', stroke: '#1976d2' },
  muted: 'var(--text-muted)' as string,
};

interface CLStep extends StepInfo {}

function lbl(g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void { drawLabel(g as Sel, x, y, text, opts); }

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 120): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 32).attr('cy', y + BOX_H / 2)
    .attr('r', 18).attr('fill', stroke);
  lbl(g, cx - w / 2 + 32, y + BOX_H / 2 + 1, String(sn), { size: 15, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 - 10, title, { size: 16, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 + 14, formula, { size: 11, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(520, text.length * 8.2 + 48);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 18).attr('width', w).attr('height', 36)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(320, text.length * 7.2 + 36);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 15).attr('width', w).attr('height', 30)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function drawBox(g: Gsel, cx: number, cy: number, w: number, h: number,
  label: string, sublabel: string, fill: string, stroke: string): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 2);
  lbl(g, cx, cy - 5, label, { size: 13, weight: '600', color: stroke });
  lbl(g, cx, cy + 13, sublabel, { size: 10, color: C.muted, font: 'monospace' });
}

function makeLCG(seed: number) {
  let s = seed | 0;
  return () => { s = (s * 1664525 + 1013904223) | 0; return ((s >>> 0) / 4294967296); };
}

function drawVector(g: Gsel, cx: number, cy: number, n: number, cellW: number, cellH: number,
  colors: string[], labelAbove?: string, labelBelow?: string): void {
  const totalW = n * cellW;
  const leftX = cx - totalW / 2;
  if (labelAbove) lbl(g, cx, cy - cellH / 2 - 12, labelAbove, { size: 9, color: C.muted, font: 'monospace' });
  for (let i = 0; i < n; i++) {
    const x = leftX + i * cellW;
    g.append('rect').attr('x', x).attr('y', cy - cellH / 2)
      .attr('width', cellW - 1).attr('height', cellH)
      .attr('rx', 2).attr('fill', colors[i] || '#eee').attr('stroke', '#ccc').attr('stroke-width', 0.5);
  }
  if (labelBelow) lbl(g, cx, cy + cellH / 2 + 14, labelBelow, { size: 9, color: C.muted, font: 'monospace' });
}

function chainArrow(g: Gsel, x1: number, y: number, x2: number, color: string): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function drawChain(g: Gsel, cy: number, boxes: { label: string; sub: string; x: number; w: number }[],
  color: string): void {
  for (const box of boxes) {
    g.append('rect').attr('x', box.x - box.w / 2).attr('y', cy - 30).attr('width', box.w).attr('height', 60)
      .attr('rx', 6).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
    lbl(g, box.x, cy - 9, box.label, { size: 10, color, font: 'monospace' });
    lbl(g, box.x, cy + 13, box.sub, { size: 12, weight: '600', color, font: 'monospace' });
  }
  for (let i = 0; i < boxes.length - 1; i++) {
    const x1 = boxes[i].x + boxes[i].w / 2;
    const x2 = boxes[i + 1].x - boxes[i + 1].w / 2;
    chainArrow(g, x1 + 4, cy, x2 - 4, color);
  }
}

function vArrow(g: Gsel, x: number, y1: number, y2: number, color: string): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]): CLStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

// ── InfoNCE variant renderer ────────────────────────────────────────

function renderInfoNCE(g: Gsel, startY: number, N: number, d: number, tau: number): { steps: CLStep[]; y: number } {
  const steps: CLStep[] = [];
  let y = startY;
  const rng = makeLCG(42);
  const showN = Math.min(N, 6);
  const showD = Math.min(d, 8);

  // Generate the full batch for mathematically correct values; only a subset is drawn.
  // z_j is a noisy augmented view of z_i: positive pairs share signal (cos ≈ 0.45),
  // so the diagonal of S actually stands out from the in-batch negatives.
  const z_i: number[][] = Array.from({ length: N }, () =>
    Array.from({ length: d }, () => rng() * 2 - 1));
  const z_j: number[][] = z_i.map((row) =>
    row.map((v) => v + (rng() * 2 - 1) * 2.0));

  // L2-normalize
  const normalize = (vec: number[]) => {
    const norm = Math.sqrt(vec.reduce((s, v) => s + v * v, 0));
    return vec.map((v) => v / norm);
  };
  const zi_n = z_i.map(normalize);
  const zj_n = z_j.map(normalize);

  // Similarity matrix
  const sim: number[][] = zi_n.map((ai) =>
    zj_n.map((bj) => ai.reduce((s, v, k) => s + v * bj[k], 0)));
  const simScaled = sim.map((row) => row.map((v) => v / tau));

  // Softmax per row
  const softmax = (row: number[]) => {
    const mx = Math.max(...row);
    const exps = row.map((v) => Math.exp(v - mx));
    const sum = exps.reduce((a, b) => a + b, 0);
    return exps.map((e) => e / sum);
  };
  const probs = simScaled.map(softmax);
  const lossVals = probs.map((row, i) => -Math.log(row[i]));
  const meanLoss = lossVals.reduce((a, b) => a + b, 0) / lossVals.length;

  // Pick a visible row with the strongest positive-pair probability for consistent examples
  const bestRow = probs.slice(0, showN).reduce((best, row, i) => row[i] > probs[best][best] ? i : best, 0);

  // ── Step 1: Input Embeddings ─────────────────────────────────────
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input: Anchor & Positive Embeddings',
      `z_i: [${N} × ${d}],  z_j: [${N} × ${d}]  — two views / paired batch`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // z_i matrix (left)
    const matW = 260, matH = 170;
    const matLeftX = CX - 380;
    drawMatrixBlock(gs as Sel, matLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'z_i', sublabel: `[${N} × ${d}]`,
      fill: C.embed.fill, stroke: C.embed.stroke,
      dimLeft: `N = ${N}`, dimTop: `d = ${d}`,
    });
    lbl(gs, matLeftX + matW / 2, rowY + matH / 2 + 18, 'anchor / view 1 embeddings',
      { size: 9, color: C.muted, font: 'monospace' });

    // z_j matrix (right)
    const matRightX = CX + 120;
    drawMatrixBlock(gs as Sel, matRightX, rowY - matH / 2, {
      width: matW, height: matH, label: 'z_j', sublabel: `[${N} × ${d}]`,
      fill: C.embed.fill, stroke: C.embed.stroke,
      dimLeft: `N`, dimTop: `d`,
    });
    lbl(gs, matRightX + matW / 2, rowY + matH / 2 + 18, 'positive / view 2 embeddings',
      { size: 9, color: C.muted, font: 'monospace' });

    // Arrow between
    drawArrow(gs as Sel, matLeftX + matW + 12, rowY, matRightX - 8, rowY, { color: C.header.stroke });

    // Pair note
    lbl(gs, CX, rowY + matH / 2 + 40,
      `pair (z_i[k], z_j[k]) is positive — all other pairs are in-batch negatives`,
      { size: 9, color: C.muted, font: 'monospace' });

    shapeEq(gs, CX, rowY + 155,
      `z_i = encoder(x_i),  z_j = encoder(x_j)  — same encoder, different views`,
      C.header.stroke);
    sampleNote(gs, CX, rowY + 155 + 42,
      `batch of N pairs provides N positive matches and N²−N negatives`, C.header.stroke);

    y = rowY + 155 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Inputs', 'Input Embeddings',
      `z_i[${N}, ${d}], z_j[${N}, ${d}]`,
      `Two sets of embeddings from the same encoder. For each index k, (z_i[k], z_j[k]) is a positive pair (same input, different augmentation/view). All other combinations serve as in-batch negatives, making the batch itself provide the contrastive signal.`,
      'step-input', C.header.stroke, C.header.fill,
      [`z_i = encoder(x_i)  # shape [${N}, ${d}]`, `z_j = encoder(x_j)  # shape [${N}, ${d}]`, `# pair (k, k) = positive, pair (k, j≠k) = negative`]));
  }

  // ── Step 2: L2-Normalize ─────────────────────────────────────────
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-norm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'L2-Normalize Embeddings',
      `ẑ = z / ||z||₂   →   ||ẑ|| = 1   (unit hypersphere)`,
      C.embed.fill, C.embed.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Show raw vector → normalized vector
    const cellW = 56, cellH = 42;
    const rawVec = z_i[bestRow];
    const normVec = zi_n[bestRow];
    const rawCX = CX - 300;
    const normCX = CX + 300;
    const totalW = showD * cellW;

    const rawColors = rawVec.map((v) => d3.interpolate('#fff', C.embed.stroke)(Math.min(1, Math.abs(v) / 2)));
    drawVector(gs, rawCX, rowY - 30, showD, cellW, cellH, rawColors,
      `z_i[${bestRow}]  (raw embedding, first ${showD} of ${d})`, `||z|| = ${Math.sqrt(rawVec.reduce((s, v) => s + v * v, 0)).toFixed(3)}`);

    const normColors = normVec.map((v) => d3.interpolate('#fff', C.embed.stroke)(Math.min(1, Math.abs(v) / 2)));
    drawVector(gs, normCX, rowY - 30, showD, cellW, cellH, normColors,
      `ẑ_i[${bestRow}]  (normalized)`, `||ẑ|| = 1.000`);

    // Arrow + formula
    drawArrow(gs as Sel, rawCX + totalW / 2 + 14, rowY - 30, normCX - totalW / 2 - 12, rowY - 30, { color: C.embed.stroke });

    // Chain showing normalization
    const chainY = rowY + 70;
    const chainBoxes = [
      { label: 'z_i[k]', sub: `raw`, x: CX - 340, w: 140 },
      { label: '||z||₂', sub: `√(Σ z²)`, x: CX - 130, w: 140 },
      { label: 'z ÷ ||z||', sub: `ẑ_i[k]`, x: CX + 80, w: 150 },
      { label: '||ẑ|| = 1', sub: `unit`, x: CX + 290, w: 140 },
    ];
    drawChain(gs, chainY, chainBoxes, C.embed.stroke);

    shapeEq(gs, CX, chainY + 70,
      `L2 normalization maps embeddings to a unit hypersphere — similarities become cos(θ) ∈ [−1, 1]`,
      C.embed.stroke);
    sampleNote(gs, CX, chainY + 70 + 42,
      `normalized embeddings: dot product = cosine similarity — bounded and stable`, C.embed.stroke);

    y = chainY + 70 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Normalize', 'L2-Normalize',
      `ẑ = z / ||z||₂`,
      `L2 normalization projects embeddings onto the unit hypersphere. After normalization, the dot product between two embeddings equals their cosine similarity, which is bounded in [−1, 1]. This ensures stable training and makes the temperature τ the sole control over the sharpness of the distribution.`,
      'step-norm', C.embed.stroke, C.embed.fill,
      [`z_i = F.normalize(z_i, dim=-1)`, `z_j = F.normalize(z_j, dim=-1)`, `# now dot(z_i[k], z_j[k]) = cos(θ) ∈ [-1, 1]`]));
  }

  // ── Step 3: Similarity Matrix ─────────────────────────────────────
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-sim', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Similarity Matrix',
      `S = ẑ_i · ẑ_jᵀ   shape: [${N} × ${N}]   diagonal = positive pairs`,
      C.sim.fill, C.sim.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Show the matmul: z_i × z_j^T
    const matW = 260, matH = 170;
    const matLeftX = CX - 400;
    drawMatrixBlock(gs as Sel, matLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'ẑ_i', sublabel: `[${N} × ${d}]`,
      fill: C.embed.fill, stroke: C.embed.stroke,
      dimLeft: `N`, dimTop: `d`,
    });

    // × symbol
    lbl(gs, matLeftX + matW + 30, rowY, '×', { size: 20, weight: '700', color: C.muted });

    // z_j^T
    const matTLeftX = CX - 100;
    drawMatrixBlock(gs as Sel, matTLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'ẑ_jᵀ', sublabel: `[${d} × ${N}]`,
      fill: C.embed.fill, stroke: C.embed.stroke,
      dimLeft: `d`, dimTop: `N`,
    });

    // → symbol
    lbl(gs, matTLeftX + matW + 30, rowY, '=', { size: 20, weight: '700', color: C.muted });

    // Result: similarity matrix [N×N]
    const simW = 260;
    const simLeftX = CX + 220;
    drawMatrixBlock(gs as Sel, simLeftX, rowY - matH / 2, {
      width: simW, height: matH, label: 'S', sublabel: `[${N} × ${N}]`,
      fill: C.sim.fill, stroke: C.sim.stroke,
      dimLeft: `N`, dimTop: `N`,
    });

    // Highlight diagonal and show values
    const cellW2 = simW / Math.min(showN, 6);
    const cellH2 = matH / Math.min(showN, 6);
    const nCells = Math.min(showN, 6);
    for (let i = 0; i < nCells; i++) {
      gs.append('rect')
        .attr('x', simLeftX + i * cellW2)
        .attr('y', rowY - matH / 2 + i * cellH2)
        .attr('width', cellW2).attr('height', cellH2)
        .attr('fill', C.sim.stroke).attr('opacity', 0.72).attr('rx', 1);
      lbl(gs, simLeftX + i * cellW2 + cellW2 / 2, rowY - matH / 2 + i * cellH2 + cellH2 / 2 + 1,
        sim[i][i].toFixed(2), { size: 8, color: '#fff', weight: '700', font: 'monospace' });
    }
    lbl(gs, simLeftX + simW / 2, rowY + matH / 2 + 18,
      `diagonal = positive pairs (cosine similarity)`,
      { size: 9, color: C.muted, font: 'monospace' });

    // Sample values
    lbl(gs, simLeftX + simW / 2, rowY + matH / 2 + 38,
      `S[${bestRow},${bestRow}] = ${sim[bestRow][bestRow].toFixed(4)}  (positive),  S[k,j≠k] = negatives`,
      { size: 9, color: C.muted, font: 'monospace' });

    shapeEq(gs, CX, rowY + 150,
      `S[i,j] = Σ_k ẑ_i[i,k] · ẑ_j[j,k]   =   cos(θ_ij)   ∈ [−1, 1]`,
      C.sim.stroke);
    sampleNote(gs, CX, rowY + 150 + 42,
      `in-batch negatives: each row i has 1 positive (j=i) and N−1 negatives`, C.sim.stroke);

    y = rowY + 150 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Similarity', 'Similarity Matrix',
      `S = ẑ_i · ẑ_jᵀ  [${N}×${N}]`,
      `The similarity matrix S is computed as the dot product of normalized embeddings. S[i,j] = cos(θ) between embedding i and embedding j. The diagonal entries S[k,k] represent positive pairs, while off-diagonal entries serve as in-batch negatives. This is the key insight of InfoNCE: the batch itself provides the negative samples.`,
      'step-sim', C.sim.stroke, C.sim.fill,
      [`S = z_i @ z_j.T  # [N, N]`, `# S[k, k] = positive pair similarity`, `# S[k, j≠k] = negative pair similarity`]));
  }

  // ── Step 4: Temperature + Softmax ─────────────────────────────────
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-softmax', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Temperature Scaling + Softmax',
      `P(j|i) = exp(S[i,j]/τ) / Σ_j exp(S[i,j]/τ)   [τ = ${tau}]`,
      C.softmax.fill, C.softmax.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Chain
    const chainY = rowY;
    const chainBoxes = [
      { label: `S[${bestRow},${bestRow}]`, sub: sim[bestRow][bestRow].toFixed(3), x: CX - 480, w: 130 },
      { label: '÷ τ', sub: (sim[bestRow][bestRow] / tau).toFixed(2), x: CX - 300, w: 120 },
      { label: 'exp(·)', sub: Math.exp(sim[bestRow][bestRow] / tau).toFixed(3), x: CX - 110, w: 130 },
      { label: '÷ Σ exp', sub: probs[bestRow][bestRow].toFixed(4), x: CX + 100, w: 140 },
      { label: `P(j|i=${bestRow})`, sub: `row ${bestRow}`, x: CX + 310, w: 130 },
    ];
    drawChain(gs, chainY, chainBoxes, C.softmax.stroke);

    // Show probability row as colored cells
    const cellW = 64, cellH = 44;
    const probColors = probs[bestRow].map((p) => d3.interpolate('#fff', C.softmax.stroke)(0.15 + p * 0.7));
    const probY = chainY + 120;
    drawVector(gs, CX, probY, showN, cellW, cellH, probColors,
      `P(j|i) for sample ${bestRow}: first ${showN} of ${N}`,
      `P(j=i) = ${probs[bestRow][bestRow].toFixed(4)} (positive),  Σ P = 1`);

    // Vertical arrow
    vArrow(gs, CX, chainY + 30, probY - cellH / 2 - 14, C.softmax.stroke);

    // Temperature explanation
    lbl(gs, CX, probY + 80,
      `τ controls sharpness: small τ → sharp distribution (confident), large τ → flat (uncertain)`,
      { size: 9, color: C.muted, font: 'monospace' });

    shapeEq(gs, CX, probY + 120,
      `P(j|i) = softmax(S[i,j] / τ)   — τ = ${tau} → ${tau < 0.1 ? 'very sharp' : tau < 0.5 ? 'moderate' : 'smooth'}`,
      C.softmax.stroke);
    sampleNote(gs, CX, probY + 120 + 42,
      `lower τ makes model more selective — pushes positive probability higher`, C.softmax.stroke);

    y = probY + 120 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Softmax', 'Temperature + Softmax',
      `P = softmax(S/τ)`,
      `Temperature scaling divides the similarity scores by τ before softmax. A small τ (e.g., 0.07) makes the distribution sharp — the model must assign high probability to the correct positive. A large τ makes it flat — the model is less discriminating. The optimal τ depends on batch size and embedding dimension.`,
      'step-softmax', C.softmax.stroke, C.softmax.fill,
      [`logits = S / tau  # temperature scaling`, `P = F.softmax(logits, dim=-1)  # [N, N]`, `# P[i, :] is a probability distribution over j`, `# P[i, i] should be close to 1 (positive pair)`]));
  }

  // ── Step 5: Loss Computation ─────────────────────────────────────
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-loss', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'InfoNCE Loss: −log P(positive)',
      `L = (1/N) Σ_i −log P(j=i | i)   =   ${meanLoss.toFixed(4)}`,
      C.loss.fill, C.loss.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Show probability matrix with diagonal highlighted
    const matW = 260, matH = 170;
    const matLeftX = CX - 360;
    drawMatrixBlock(gs as Sel, matLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'P', sublabel: `[${N} × ${N}]`,
      fill: C.softmax.fill, stroke: C.softmax.stroke,
      dimLeft: `N`, dimTop: `N`,
    });
    // Highlight diagonal
    const cellW2 = matW / Math.min(showN, 6);
    const cellH2 = matH / Math.min(showN, 6);
    for (let i = 0; i < Math.min(showN, 6); i++) {
      gs.append('rect')
        .attr('x', matLeftX + i * cellW2)
        .attr('y', rowY - matH / 2 + i * cellH2)
        .attr('width', cellW2).attr('height', cellH2)
        .attr('fill', C.loss.stroke).attr('opacity', 0.3).attr('rx', 1);
    }
    lbl(gs, matLeftX + matW / 2, rowY + matH / 2 + 18,
      `gather diagonal P[i,i] — positive pair probabilities`,
      { size: 9, color: C.muted, font: 'monospace' });

    // Arrow to gathered vector
    const gathCX = CX + 100;
    const gathCellW = 72, gathCellH = 46;
    const gathTotalW = showN * gathCellW;
    drawArrow(gs as Sel, matLeftX + matW + 14, rowY, gathCX - gathTotalW / 2 - 12, rowY, { color: C.loss.stroke });

    const gathColors = probs.map((row, i) =>
      d3.interpolate('#fff', C.loss.stroke)(0.2 + row[i] * 0.6));
    drawVector(gs, gathCX, rowY, showN, gathCellW, gathCellH, gathColors,
      `P[i,i] — first ${showN} of ${N} diagonals`, `positive probabilities (e.g. sample ${bestRow} = ${probs[bestRow][bestRow].toFixed(4)})`);

    // Chain: −log → mean
    const chainY = rowY + 120;
    const chainBoxes = [
      { label: `P[${bestRow},${bestRow}]`, sub: probs[bestRow][bestRow].toFixed(4), x: CX - 340, w: 140 },
      { label: '−log(·)', sub: lossVals[bestRow].toFixed(4), x: CX - 130, w: 140 },
      { label: 'mean(·)', sub: `÷ ${N}`, x: CX + 80, w: 130 },
      { label: 'L', sub: meanLoss.toFixed(4), x: CX + 270, w: 120 },
    ];
    drawChain(gs, chainY, chainBoxes, C.loss.stroke);

    vArrow(gs, gathCX, rowY + gathCellH / 2 + 16, chainY - 30, C.loss.stroke);

    shapeEq(gs, CX, chainY + 70,
      `L = −(1/N) Σ_i log P(j=i | i)   =   cross_entropy(S/τ, arange(N))`,
      C.loss.stroke);
    sampleNote(gs, CX, chainY + 70 + 42,
      `minimizing L ↔ maximizing P(positive) — pulling matched pairs together`, C.loss.stroke);

    y = chainY + 70 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Loss', 'InfoNCE Loss',
      `L = mean(−log P[i,i])`,
      `The InfoNCE loss gathers the diagonal probabilities (positive pairs), takes the negative log, and averages over the batch. This is equivalent to cross-entropy where the "target" for each row i is index i itself. Minimizing this loss maximizes the probability of matching the correct positive pair while pushing down probabilities of all in-batch negatives.`,
      'step-loss', C.loss.stroke, C.loss.fill,
      [`# Gather positive pair probabilities`, `pos_logprobs = -torch.log(P.diagonal())`, `loss = pos_logprobs.mean()`, `# OR equivalently:`, `loss = F.cross_entropy(S / tau, torch.arange(N))`]));
  }

  return { steps, y };
}

// ── NT-Xent variant renderer ────────────────────────────────────────

function renderNTXent(g: Gsel, startY: number, N: number, d: number, tau: number): { steps: CLStep[]; y: number } {
  const steps: CLStep[] = [];
  let y = startY;
  const rng = makeLCG(77);
  const showN = Math.min(N, 6);

  // Generate the full batch for mathematically correct values; only a subset is drawn.
  // z_j is a noisy augmented view of z_i: positive pairs share signal (cos ≈ 0.45),
  // so the diagonal of S actually stands out from the in-batch negatives.
  const z_i: number[][] = Array.from({ length: N }, () =>
    Array.from({ length: d }, () => rng() * 2 - 1));
  const z_j: number[][] = z_i.map((row) =>
    row.map((v) => v + (rng() * 2 - 1) * 2.0));
  const normalize = (vec: number[]) => {
    const norm = Math.sqrt(vec.reduce((s, v) => s + v * v, 0));
    return vec.map((v) => v / norm);
  };
  const zi_n = z_i.map(normalize);
  const zj_n = z_j.map(normalize);
  const sim: number[][] = zi_n.map((ai) =>
    zj_n.map((bj) => ai.reduce((s, v, k) => s + v * bj[k], 0)));
  const simScaled = sim.map((row) => row.map((v) => v / tau));
  const softmax = (row: number[]) => {
    const mx = Math.max(...row);
    const exps = row.map((v) => Math.exp(v - mx));
    const sum = exps.reduce((a, b) => a + b, 0);
    return exps.map((e) => e / sum);
  };
  const probs_ij = simScaled.map(softmax);
  const simT = simScaled[0].map((_, j) => simScaled.map((row) => row[j]));
  const probs_ji = simT.map(softmax);
  const loss_ij = probs_ij.map((row, i) => -Math.log(row[i]));
  const loss_ji = probs_ji.map((row, i) => -Math.log(row[i]));
  const meanLoss = (loss_ij.reduce((a, b) => a + b, 0) + loss_ji.reduce((a, b) => a + b, 0)) / (2 * loss_ij.length);

  // Pick a visible row with the strongest row-wise positive-pair probability for consistent examples
  const bestRow = probs_ij.slice(0, showN).reduce((best, row, i) => row[i] > probs_ij[best][best] ? i : best, 0);

  // ── Step 1: Input + L2-Normalize ─────────────────────────────────
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input: Two Views + L2-Normalize',
      `z_i, z_j: [${N} × ${d}]  →  ẑ_i, ẑ_j: unit norm`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const matW = 260, matH = 160;
    const matLeftX = CX - 380;
    drawMatrixBlock(gs as Sel, matLeftX, rowY - matH / 2, {
      width: matW, height: matH, label: 'ẑ_i', sublabel: `[${N} × ${d}] normalized`,
      fill: C.embed.fill, stroke: C.embed.stroke,
      dimLeft: `N = ${N}`, dimTop: `d = ${d}`,
    });

    const matRightX = CX + 120;
    drawMatrixBlock(gs as Sel, matRightX, rowY - matH / 2, {
      width: matW, height: matH, label: 'ẑ_j', sublabel: `[${N} × ${d}] normalized`,
      fill: C.embed.fill, stroke: C.embed.stroke,
      dimLeft: `N`, dimTop: `d`,
    });

    drawArrow(gs as Sel, matLeftX + matW + 14, rowY, matRightX - 10, rowY, { color: C.header.stroke });

    shapeEq(gs, CX, rowY + 130,
      `ẑ_i = z_i / ||z_i||₂,  ẑ_j = z_j / ||z_j||₂   — both on unit hypersphere`,
      C.header.stroke);
    sampleNote(gs, CX, rowY + 130 + 42,
      `SimCLR: two augmented views from same image — NT-Xent is symmetric`, C.header.stroke);

    y = rowY + 130 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Inputs', 'Input + Normalize',
      `ẑ_i[${N}, ${d}], ẑ_j[${N}, ${d}]`,
      `NT-Xent (Normalized Temperature-scaled Cross Entropy) is used in SimCLR. Two augmented views of each input are encoded and L2-normalized. The key difference from InfoNCE is that NT-Xent is symmetric: it computes the loss in both directions (i→j and j→i) and averages.`,
      'step-input', C.header.stroke, C.header.fill,
      [`z_i = F.normalize(encoder(x_i), dim=-1)`, `z_j = F.normalize(encoder(x_j), dim=-1)`]));
  }

  // ── Step 2: Similarity Matrix + Temperature ──────────────────────
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-sim', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Similarity Matrix + Temperature',
      `S = ẑ_i · ẑ_jᵀ / τ   shape: [${N} × ${N}]   [τ = ${tau}]`,
      C.sim.fill, C.sim.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Chain
    const chainY = rowY;
    const chainBoxes = [
      { label: 'ẑ_i · ẑ_jᵀ', sub: `cos(θ)`, x: CX - 380, w: 150 },
      { label: '÷ τ', sub: `scale`, x: CX - 170, w: 120 },
      { label: `S[${bestRow},${bestRow}]`, sub: simScaled[bestRow][bestRow].toFixed(2), x: CX + 40, w: 130 },
      { label: 'S matrix', sub: `[${N}×${N}]`, x: CX + 250, w: 130 },
    ];
    drawChain(gs, chainY, chainBoxes, C.sim.stroke);

    // Matrix visualization
    const matW = 260, matH = 170;
    const matLeftX = CX - matW / 2;
    drawMatrixBlock(gs as Sel, matLeftX, rowY + 90, {
      width: matW, height: matH, label: 'S/τ', sublabel: `[${N} × ${N}]`,
      fill: C.sim.fill, stroke: C.sim.stroke,
      dimLeft: `N`, dimTop: `N`,
    });

    // Highlight diagonal and label values
    const cellW2 = matW / Math.min(showN, 6);
    const cellH2 = matH / Math.min(showN, 6);
    const nCells = Math.min(showN, 6);
    for (let i = 0; i < nCells; i++) {
      gs.append('rect')
        .attr('x', matLeftX + i * cellW2)
        .attr('y', rowY + 90 + i * cellH2)
        .attr('width', cellW2).attr('height', cellH2)
        .attr('fill', C.sim.stroke).attr('opacity', 0.72).attr('rx', 1);
      lbl(gs, matLeftX + i * cellW2 + cellW2 / 2, rowY + 90 + i * cellH2 + cellH2 / 2 + 1,
        simScaled[i][i].toFixed(1), { size: 8, color: '#fff', weight: '700', font: 'monospace' });
    }

    vArrow(gs, CX, chainY + 30, rowY + 90 - 8, C.sim.stroke);

    lbl(gs, CX, rowY + 90 + matH + 18,
      `diagonal = positive pair similarities — all off-diagonal are negatives`,
      { size: 9, color: C.muted, font: 'monospace' });

    shapeEq(gs, CX, rowY + 90 + matH + 55,
      `S[i,j] = ẑ_i[i] · ẑ_j[j] / τ   —   asymmetric matrix of scaled cosine similarities (ẑ_i ≠ ẑ_j)`,
      C.sim.stroke);
    sampleNote(gs, CX, rowY + 90 + matH + 55 + 42,
      `temperature τ = ${tau}: controls concentration of probability mass`, C.sim.stroke);

    y = rowY + 90 + matH + 55 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Similarity', 'Similarity + Temperature',
      `S = ẑ_i · ẑ_jᵀ / τ`,
      `The similarity matrix is computed by dot product of normalized embeddings, divided by temperature τ. The diagonal contains positive pair similarities. The matrix is not necessarily symmetric (ẑ_i ≠ ẑ_j), which is why NT-Xent computes loss in both directions.`,
      'step-sim', C.sim.stroke, C.sim.fill,
      [`S = z_i @ z_j.T / tau  # [N, N]`, `# S[k, k] = positive pair`, `# S[k, j≠k] = negative pair`]));
  }

  // ── Step 3: Bidirectional Softmax ────────────────────────────────
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-softmax', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Bidirectional Softmax',
      `P(j|i) = softmax(S[i,:])   and   P(i|j) = softmax(S[:,j])`,
      C.softmax.fill, C.softmax.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Left: P(j|i) — row-wise softmax
    const leftCX = CX - 300;
    const cellW = 56, cellH = 42;
    const probColors_ij = probs_ij[bestRow].map((p) => d3.interpolate('#fff', C.softmax.stroke)(0.15 + p * 0.7));
    drawVector(gs, leftCX, rowY, showN, cellW, cellH, probColors_ij,
      `P(j|i=${bestRow}) — row-wise softmax, first ${showN} of ${N}`, `P(j=i|i) = ${probs_ij[bestRow][bestRow].toFixed(4)}`);

    // Right: P(i|j) — column-wise softmax
    const rightCX = CX + 300;
    const probColors_ji = probs_ji[bestRow].map((p) => d3.interpolate('#fff', C.softmax.stroke)(0.15 + p * 0.7));
    drawVector(gs, rightCX, rowY, showN, cellW, cellH, probColors_ji,
      `P(i|j=${bestRow}) — column-wise softmax, first ${showN} of ${N}`, `P(i=j|j) = ${probs_ji[bestRow][bestRow].toFixed(4)}`);

    // Arrow between
    lbl(gs, CX, rowY, '⟷', { size: 20, weight: '700', color: C.softmax.stroke });

    lbl(gs, CX, rowY + 55, `symmetric: compute loss in BOTH directions → more training signal`,
      { size: 9, color: C.muted, font: 'monospace' });

    shapeEq(gs, CX, rowY + 105,
      `P(j|i) = softmax(S[i,:]/τ)   P(i|j) = softmax(S[:,j]/τ)`,
      C.softmax.stroke);
    sampleNote(gs, CX, rowY + 105 + 42,
      `row-wise: each anchor i finds its positive j; column-wise: each positive j finds its anchor i`, C.softmax.stroke);

    y = rowY + 105 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Softmax', 'Bidirectional Softmax',
      `P(j|i) = softmax(S[i,:])`,
      `NT-Xent computes softmax in both directions: P(j|i) (row-wise, anchor→positive) and P(i|j) (column-wise, positive→anchor). This symmetric formulation provides 2N gradient signals instead of N, making training more efficient and the learned representations more robust.`,
      'step-softmax', C.softmax.stroke, C.softmax.fill,
      [`P_ij = F.softmax(S, dim=-1)  # row-wise`, `P_ji = F.softmax(S.t(), dim=-1)  # column-wise`, `# both directions provide gradient signal`]));
  }

  // ── Step 4: Symmetric Loss ───────────────────────────────────────
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-loss', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Symmetric NT-Xent Loss',
      `L = ½ · [mean(−log P(j=i|i)) + mean(−log P(i=j|j))]   =   ${meanLoss.toFixed(4)}`,
      C.loss.fill, C.loss.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Two loss vectors
    const cellW = 72, cellH = 46;
    const leftCX = CX - 260;
    const rightCX = CX + 260;

    const lossColors_ij = loss_ij.length > showN ? loss_ij.slice(0, showN).map((v) => d3.interpolate('#fff', C.loss.stroke)(0.2 + v * 0.3)) :
      loss_ij.map((v) => d3.interpolate('#fff', C.loss.stroke)(0.2 + v * 0.3));
    drawVector(gs, leftCX, rowY - 50, showN, cellW, cellH, lossColors_ij,
      `−log P(j=i|i) — row loss, first ${showN} of ${N}`, `per-sample`);

    const lossColors_ji = loss_ji.slice(0, showN).map((v) => d3.interpolate('#fff', C.loss.stroke)(0.2 + v * 0.3));
    drawVector(gs, rightCX, rowY - 50, showN, cellW, cellH, lossColors_ji,
      `−log P(i=j|j) — col loss, first ${showN} of ${N}`, `per-sample`);

    // + symbol and mean
    lbl(gs, CX, rowY - 50, '+', { size: 20, weight: '700', color: C.loss.stroke });

    // Chain below
    const chainY = rowY + 70;
    const chainBoxes = [
      { label: 'L_ij', sub: `row CE`, x: CX - 380, w: 130 },
      { label: 'L_ji', sub: `col CE`, x: CX - 190, w: 130 },
      { label: 'L_ij + L_ji', sub: `sum`, x: CX + 20, w: 150 },
      { label: '÷ 2N', sub: `mean`, x: CX + 230, w: 120 },
    ];
    drawChain(gs, chainY, chainBoxes, C.loss.stroke);

    // Loss circle
    const lossCX = CX;
    const lossY = chainY + 90;
    vArrow(gs, lossCX, chainY + 30, lossY - 44, C.loss.stroke);
    gs.append('circle').attr('cx', lossCX).attr('cy', lossY).attr('r', 44)
      .attr('fill', C.loss.fill).attr('stroke', C.loss.stroke).attr('stroke-width', 2.5);
    lbl(gs, lossCX, lossY - 10, 'L', { size: 16, weight: '700', color: C.loss.stroke });
    lbl(gs, lossCX, lossY + 10, meanLoss.toFixed(4), { size: 9, color: C.loss.stroke, font: 'monospace' });

    shapeEq(gs, CX, lossY + 70,
      `L = (1/2N) Σ_i [−log P(j=i|i) − log P(i=j|j)]`,
      C.loss.stroke);
    sampleNote(gs, CX, lossY + 70 + 42,
      `symmetric loss = 2× more gradient signal per batch compared to InfoNCE`, C.loss.stroke);

    y = lossY + 70 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Loss', 'Symmetric Loss',
      `L = ½(L_ij + L_ji)`,
      `The NT-Xent loss averages the cross-entropy from both directions. L_ij = mean(−log P(j=i|i)) and L_ji = mean(−log P(i=j|j)). The final loss L = (L_ij + L_ji) / 2 provides symmetric gradients, pulling positive pairs together from both sides. This is more data-efficient than one-directional InfoNCE.`,
      'step-loss', C.loss.stroke, C.loss.fill,
      [`loss_ij = -torch.log(P_ij.diagonal()).mean()`, `loss_ji = -torch.log(P_ji.diagonal()).mean()`, `loss = (loss_ij + loss_ji) / 2`, `# OR:`, `loss = F.cross_entropy(S, torch.arange(N))`, `loss += F.cross_entropy(S.t(), torch.arange(N))`, `loss /= 2`]));
  }

  // ── Step 5: Gradient & Effect ────────────────────────────────────
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-effect', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Gradient Signal & Effect',
      `∂L/∂S[i,j] = P(i,j) − 𝟙[j=i]  — pushes positives up, negatives down`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Show gradient matrix concept — illustrative values for clarity
    // (actual τ=0.07 produces very sharp distributions where most values round to 0)
    const cols = [CX - 320, CX, CX + 320];
    const labels = ['Positive pair (j=i)', 'Hard negative (j≠i)', 'Easy negative (j≠i)'];
    const pVals = [0.85, 0.08, 0.02];
    const gradVals = [pVals[0] - 1, pVals[1] - 0, pVals[2] - 0];
    const colors = [C.sim.stroke, C.loss.stroke, C.muted];

    for (let i = 0; i < 3; i++) {
      const cx2 = cols[i];
      const c2 = colors[i];
      const barH = Math.abs(gradVals[i]) * 100;

      // Probability bar
      gs.append('rect').attr('x', cx2 - 40).attr('y', rowY - pVals[i] * 100)
        .attr('width', 80).attr('height', pVals[i] * 100)
        .attr('fill', c2).attr('opacity', 0.3).attr('rx', 3);
      lbl(gs, cx2, rowY + 18, `P = ${pVals[i].toFixed(3)}`, { size: 9, color: c2, font: 'monospace' });

      // Gradient bar
      const gy = rowY + 130;
      gs.append('rect').attr('x', cx2 - 30).attr('y', gy - barH).attr('width', 60).attr('height', barH)
        .attr('fill', c2).attr('opacity', 0.5).attr('rx', 3);
      lbl(gs, cx2, gy + 18, labels[i], { size: 8, color: c2, font: 'monospace' });
      lbl(gs, cx2, gy - barH - 10, `∂L/∂S = ${gradVals[i].toFixed(3)}`, { size: 9, color: c2, weight: '600', font: 'monospace' });
    }

    shapeEq(gs, CX, rowY + 220,
      `∂L/∂S[i,j] = P(i,j) − 𝟙[j=i]   —   same elegant gradient as cross-entropy`,
      C.header.stroke);
    sampleNote(gs, CX, rowY + 220 + 42,
      `illustrative values — hard negatives (high P but should be 0) get large gradient, focus learning`, C.header.stroke);

    y = rowY + 220 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Gradient', 'Gradient & Effect',
      `∂L/∂S = P − 𝟙_target`,
      `The gradient of NT-Xent w.r.t. the similarity matrix is ∂L/∂S[i,j] = P(i,j) − 𝟙[j=i]. For positive pairs (j=i), the gradient is P−1 (negative, pushing similarity up). For negatives (j≠i), the gradient is P (positive, pushing similarity down). Hard negatives (high P for wrong pair) get the largest gradient — the model focuses learning where it's most confused.`,
      'step-effect', C.header.stroke, C.header.fill,
      [`# Gradient is same as cross-entropy:`, `# dL/dS[i,j] = P[i,j] - one_hot[j==i]`, `# Positive (j=i): grad = P-1 (push UP)`, `# Negative (j≠i): grad = P (push DOWN)`, `# Hard negatives: high P → large gradient`]));
  }

  return { steps, y };
}

// ── Triplet variant renderer ────────────────────────────────────────

function renderTriplet(g: Gsel, startY: number, N: number, d: number): { steps: CLStep[]; y: number } {
  const steps: CLStep[] = [];
  let y = startY;
  const rng = makeLCG(123);
  const showD = Math.min(d, 8);
  const margin = 1.0;

  // Generate the full-dimensional triplet for mathematically correct distances; only a subset is drawn.
  // The positive is a noisy view of the anchor (cos ≈ 0.7), the negative is unrelated:
  // d(a,p) < d(a,n) as a correctly-ranked but within-margin example.
  const anchor = Array.from({ length: d }, () => rng() * 2 - 1);
  const positive = anchor.map((v) => v + (rng() * 2 - 1) * 1.0);
  const negative = Array.from({ length: d }, () => rng() * 2 - 1);

  const normalize = (vec: number[]) => {
    const norm = Math.sqrt(vec.reduce((s, v) => s + v * v, 0));
    return vec.map((v) => v / norm);
  };
  const a_n = normalize(anchor);
  const p_n = normalize(positive);
  const n_n = normalize(negative);

  // Distances
  const dist = (a: number[], b: number[]) => Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0));
  const d_ap = dist(a_n, p_n);
  const d_an = dist(a_n, n_n);
  const rawLoss = Math.max(0, d_ap - d_an + margin);

  // ── Step 1: Input Embeddings ─────────────────────────────────────
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input: Anchor, Positive, Negative',
      `anchor: [${N} × ${d}],  positive: [${N} × ${d}],  negative: [${N} × ${d}]`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const matW = 240, matH = 150;
    const positions = [
      { x: CX - 380, label: 'anchor', sub: `[${N} × ${d}]`, color: C.triplet, desc: 'reference sample' },
      { x: CX, label: 'positive', sub: `[${N} × ${d}]`, color: C.sim, desc: 'same class as anchor' },
      { x: CX + 380, label: 'negative', sub: `[${N} × ${d}]`, color: C.loss, desc: 'different class' },
    ];

    for (const pos of positions) {
      drawMatrixBlock(gs as Sel, pos.x - matW / 2, rowY - matH / 2, {
        width: matW, height: matH, label: pos.label, sublabel: pos.sub,
        fill: pos.color.fill, stroke: pos.color.stroke,
        dimLeft: `N`, dimTop: `d`,
      });
      lbl(gs, pos.x, rowY + matH / 2 + 18, pos.desc, { size: 9, color: C.muted, font: 'monospace' });
    }

    // Arrows between
    drawArrow(gs as Sel, positions[0].x + matW / 2 + 14, rowY, positions[1].x - matW / 2 - 10, rowY, { color: C.header.stroke });
    drawArrow(gs as Sel, positions[1].x + matW / 2 + 14, rowY, positions[2].x - matW / 2 - 10, rowY, { color: C.header.stroke });

    shapeEq(gs, CX, rowY + 130,
      `triplet (a, p, n): anchor and positive from same class, negative from different class`,
      C.header.stroke);
    sampleNote(gs, CX, rowY + 130 + 42,
      `mining strategy determines which triplets are selected — hard negatives improve training`, C.header.stroke);

    y = rowY + 130 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Inputs', 'Anchor/Positive/Negative',
      `anchor, positive, negative [${N}, ${d}]`,
      `Triplet loss requires explicitly sampled triplets: an anchor, a positive (same class), and a negative (different class). The quality of negative sampling is critical — hard negatives (close to anchor but wrong class) provide the most learning signal. This is simpler than InfoNCE but requires explicit negative mining.`,
      'step-input', C.header.stroke, C.header.fill,
      [`anchor = encoder(x_a)    # same class`, `positive = encoder(x_p)   # same class`, `negative = encoder(x_n)  # different class`]));
  }

  // ── Step 2: L2-Normalize ─────────────────────────────────────────
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-norm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'L2-Normalize Embeddings',
      `â = a/||a||,  p̂ = p/||p||,  n̂ = n/||n||   →   unit hypersphere`,
      C.embed.fill, C.embed.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const cellW = 60, cellH = 44;

    // Three vectors: normalized
    const vecs = [
      { data: a_n, cx: CX - 380, label: `â (anchor), first ${showD} of ${d}`, color: C.triplet.stroke },
      { data: p_n, cx: CX, label: `p̂ (positive), first ${showD} of ${d}`, color: C.sim.stroke },
      { data: n_n, cx: CX + 380, label: `n̂ (negative), first ${showD} of ${d}`, color: C.loss.stroke },
    ];

    for (const vec of vecs) {
      const colors = vec.data.map((v) => d3.interpolate('#fff', vec.color)(Math.min(1, Math.abs(v) / 2)));
      drawVector(gs, vec.cx, rowY, showD, cellW, cellH, colors,
        vec.label, `||·|| = 1.000`);
    }

    // Chain
    const chainY = rowY + 90;
    const chainBoxes = [
      { label: 'a, p, n', sub: `raw`, x: CX - 340, w: 140 },
      { label: '÷ ||·||₂', sub: `normalize`, x: CX - 130, w: 140 },
      { label: 'â, p̂, n̂', sub: `unit`, x: CX + 80, w: 140 },
      { label: 'cos(θ)', sub: `similarity`, x: CX + 290, w: 140 },
    ];
    drawChain(gs, chainY, chainBoxes, C.embed.stroke);

    shapeEq(gs, CX, chainY + 70,
      `normalization → dot product = cosine similarity ∈ [−1, 1]`,
      C.embed.stroke);
    sampleNote(gs, CX, chainY + 70 + 42,
      `all three embeddings projected to unit sphere — distances become angular`, C.embed.stroke);

    y = chainY + 70 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Normalize', 'L2-Normalize',
      `â = a/||a||₂,  p̂ = p/||p||₂,  n̂ = n/||n||₂`,
      `All three embeddings are L2-normalized to the unit hypersphere. After normalization, Euclidean distance is equivalent to angular distance: ||â − p̂||₂ = √(2 − 2cos(θ)). This ensures the margin hyperparameter operates in a bounded, stable range.`,
      'step-norm', C.embed.stroke, C.embed.fill,
      [`a = F.normalize(a, dim=-1)`, `p = F.normalize(p, dim=-1)`, `n = F.normalize(n, dim=-1)`]));
  }

  // ── Step 3: Distance Computation ─────────────────────────────────
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-dist', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Euclidean Distance Computation',
      `d(a,p) = ||â − p̂||₂   d(a,n) = ||â − n̂||₂`,
      C.sim.fill, C.sim.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Left: d(a,p)
    const leftCX = CX - 280;
    const leftBoxes = [
      { label: 'â − p̂', sub: `diff`, x: leftCX - 190, w: 130 },
      { label: 'Σ (·)²', sub: `sq sum`, x: leftCX, w: 130 },
      { label: '√(·)', sub: d_ap.toFixed(4), x: leftCX + 190, w: 130 },
    ];
    drawChain(gs, rowY - 50, leftBoxes, C.sim.stroke);
    drawBox(gs, leftCX + 190, rowY + 25, 140, 56, 'd(a,p)', d_ap.toFixed(4), C.sim.fill, C.sim.stroke);
    vArrow(gs, leftCX + 190, rowY - 20, rowY - 3, C.sim.stroke);

    // Right: d(a,n)
    const rightCX = CX + 280;
    const rightBoxes = [
      { label: 'â − n̂', sub: `diff`, x: rightCX - 190, w: 130 },
      { label: 'Σ (·)²', sub: `sq sum`, x: rightCX, w: 130 },
      { label: '√(·)', sub: d_an.toFixed(4), x: rightCX + 190, w: 130 },
    ];
    drawChain(gs, rowY - 50, rightBoxes, C.loss.stroke);
    drawBox(gs, rightCX + 190, rowY + 25, 140, 56, 'd(a,n)', d_an.toFixed(4), C.loss.fill, C.loss.stroke);
    vArrow(gs, rightCX + 190, rowY - 20, rowY - 3, C.loss.stroke);

    // Comparison
    lbl(gs, CX, rowY, d_ap < d_an ? 'd(a,p) < d(a,n) ✓' : 'd(a,p) ≥ d(a,n) ✗',
      { size: 14, weight: '700', color: d_ap < d_an ? C.sim.stroke : C.loss.stroke });

    shapeEq(gs, CX, rowY + 115,
      `d(a,p) = √(Σ_k (â_k − p̂_k)²)   d(a,n) = √(Σ_k (â_k − n̂_k)²)`,
      C.sim.stroke);
    sampleNote(gs, CX, rowY + 115 + 42,
      `goal: d(a,p) < d(a,n) — anchor closer to positive than to negative`, C.sim.stroke);

    y = rowY + 115 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Distance', 'Distance Computation',
      `d_ap = ||â−p̂||,  d_an = ||â−n̂||`,
      `Euclidean distances are computed between the anchor and both the positive and negative embeddings. The goal is for d(a,p) (distance to positive) to be smaller than d(a,n) (distance to negative) by at least a margin. If this is already satisfied, the loss is zero — the triplet is "easy".`,
      'step-dist', C.sim.stroke, C.sim.fill,
      [`d_ap = (a - p).pow(2).sum(dim=-1).sqrt()`, `d_an = (a - n).pow(2).sum(dim=-1).sqrt()`]));
  }

  // ── Step 4: Triplet Loss Formula ─────────────────────────────────
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-loss', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Triplet Loss: max(0, d_ap − d_an + m)',
      `L = max(0, d(a,p) − d(a,n) + margin)   [m = ${margin}]   =   ${rawLoss.toFixed(4)}`,
      C.loss.fill, C.loss.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Chain
    const chainY = rowY;
    const chainBoxes = [
      { label: 'd(a,p)', sub: d_ap.toFixed(3), x: CX - 440, w: 130 },
      { label: 'd(a,n)', sub: d_an.toFixed(3), x: CX - 230, w: 140 },
      { label: `+ m`, sub: `${margin}`, x: CX - 20, w: 110 },
      { label: 'sum', sub: (d_ap - d_an + margin).toFixed(3), x: CX + 150, w: 130 },
      { label: 'max(0, ·)', sub: rawLoss.toFixed(3), x: CX + 340, w: 140 },
    ];
    drawChain(gs, chainY, chainBoxes, C.loss.stroke);

    // Loss circle
    const lossY = chainY + 110;
    vArrow(gs, CX, chainY + 30, lossY - 44, C.loss.stroke);
    gs.append('circle').attr('cx', CX).attr('cy', lossY).attr('r', 44)
      .attr('fill', C.loss.fill).attr('stroke', C.loss.stroke).attr('stroke-width', 2.5);
    lbl(gs, CX, lossY - 10, 'L', { size: 16, weight: '700', color: C.loss.stroke });
    lbl(gs, CX, lossY + 10, rawLoss.toFixed(4), { size: 9, color: C.loss.stroke, font: 'monospace' });

    // Hinge explanation
    const caseY = lossY + 90;
    const cases = [
      { label: 'd_ap < d_an − m → L = 0 (easy)', color: C.sim.stroke },
      { label: 'd_ap ≈ d_an → L ≈ m (borderline)', color: C.softmax.stroke },
      { label: 'd_ap > d_an → L > m (hard)', color: C.loss.stroke },
    ];
    for (let i = 0; i < cases.length; i++) {
      const bx = CX - 360 + i * 280;
      gs.append('rect').attr('x', bx - 110).attr('y', caseY).attr('width', 220).attr('height', 50)
        .attr('rx', 6).attr('fill', '#fff').attr('stroke', cases[i].color).attr('stroke-width', 1.5);
      lbl(gs, bx, caseY + 25, cases[i].label, { size: 9, color: cases[i].color, font: 'monospace' });
    }

    shapeEq(gs, CX, caseY + 90,
      `L = max(0, ||a−p|| − ||a−n|| + m)   —   hinge loss with margin m`,
      C.loss.stroke);
    sampleNote(gs, CX, caseY + 90 + 42,
      `margin m ensures minimum gap between positive and negative distances`, C.loss.stroke);

    y = caseY + 90 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Loss', 'Triplet Loss',
      `L = max(0, d_ap − d_an + m)`,
      `The triplet loss is a hinge function: L = max(0, d(a,p) − d(a,n) + m). When the anchor is already closer to the positive than to the negative by at least margin m, the loss is zero (easy triplet). Otherwise, the loss is positive, pushing the positive closer and the negative farther. The margin m ensures a minimum separation gap, preventing embeddings from collapsing to a single point.`,
      'step-loss', C.loss.stroke, C.loss.fill,
      [`loss = F.relu(d_ap - d_an + margin)`, `# OR:`, `loss = torch.clamp(d_ap - d_an + margin, min=0)`, `loss = loss.mean()`]));
  }

  // ── Step 5: Embedding Space Visualization ───────────────────────
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-space', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Embedding Space & Gradient Effect',
      `pull d(a,p) ↓,  push d(a,n) ↑  →  margin-separated clusters`,
      C.header.fill, C.header.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Draw 2D embedding space with points
    const spaceW = 600, spaceH = 260;
    const spaceCX = CX, spaceCY = rowY + spaceH / 2;

    // Border
    gs.append('rect').attr('x', spaceCX - spaceW / 2).attr('y', rowY)
      .attr('width', spaceW).attr('height', spaceH)
      .attr('rx', 8).attr('fill', '#fafafa').attr('stroke', '#ddd').attr('stroke-width', 1);

    // Anchor point (center)
    const aX = spaceCX - 80, aY = spaceCY;
    gs.append('circle').attr('cx', aX).attr('cy', aY).attr('r', 9)
      .attr('fill', C.triplet.stroke).attr('stroke', '#fff').attr('stroke-width', 2);
    lbl(gs, aX, aY - 18, 'anchor', { size: 9, color: C.triplet.stroke, font: 'monospace' });

    // Positive (close to anchor, should be closer)
    const pX = aX + 90, pY = aY - 50;
    gs.append('circle').attr('cx', pX).attr('cy', pY).attr('r', 9)
      .attr('fill', C.sim.stroke).attr('stroke', '#fff').attr('stroke-width', 2);
    lbl(gs, pX, pY - 18, 'positive', { size: 9, color: C.sim.stroke, font: 'monospace' });

    // Negative (far from anchor)
    const nX = spaceCX + 180, nY = spaceCY + 60;
    gs.append('circle').attr('cx', nX).attr('cy', nY).attr('r', 9)
      .attr('fill', C.loss.stroke).attr('stroke', '#fff').attr('stroke-width', 2);
    lbl(gs, nX, nY + 20, 'negative', { size: 9, color: C.loss.stroke, font: 'monospace' });

    // Arrows showing gradient direction
    drawArrow(gs as Sel, aX, aY, pX, pY, { color: C.sim.stroke });  // pull together
    drawArrow(gs as Sel, aX, aY, nX, nY, { color: C.loss.stroke });  // push apart

    // Labels on arrows (offset so they don't overlap arrow shafts)
    lbl(gs, (aX + pX) / 2 - 24, (aY + pY) / 2 - 10, 'pull ↓', { size: 8, color: C.sim.stroke, font: 'monospace' });
    lbl(gs, (aX + nX) / 2 + 6, (aY + nY) / 2 + 12, 'push ↑', { size: 8, color: C.loss.stroke, font: 'monospace' });

    // Other negative samples (background)
    const rng2 = makeLCG(55);
    for (let i = 0; i < 8; i++) {
      const bx = spaceCX - spaceW / 2 + 40 + rng2() * (spaceW - 80);
      const by = rowY + 30 + rng2() * (spaceH - 60);
      gs.append('circle').attr('cx', bx).attr('cy', by).attr('r', 3)
        .attr('fill', C.loss.stroke).attr('opacity', 0.2);
    }

    // Other positive samples
    for (let i = 0; i < 4; i++) {
      const bx = aX + (rng2() - 0.5) * 80;
      const by = aY + (rng2() - 0.5) * 80;
      gs.append('circle').attr('cx', bx).attr('cy', by).attr('r', 3)
        .attr('fill', C.sim.stroke).attr('opacity', 0.3);
    }

    // Margin boundary
    gs.append('circle').attr('cx', aX).attr('cy', aY).attr('r', 130)
      .attr('fill', 'none').attr('stroke', C.muted).attr('stroke-width', 1).attr('stroke-dasharray', '4,3');
    lbl(gs, aX - 120, aY - 105, 'margin boundary', { size: 8, color: C.muted, font: 'monospace' });

    shapeEq(gs, CX, rowY + spaceH + 40,
      `gradient: ∂L/∂a = 2(a−p)/d_ap − 2(a−n)/d_an   (when L > 0)`,
      C.header.stroke);
    sampleNote(gs, CX, rowY + spaceH + 40 + 42,
      `negative mining: hard negatives (close to anchor) provide the most signal`, C.header.stroke);

    y = rowY + spaceH + 40 + 42 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Effect', 'Embedding Space Effect',
      `pull a→p,  push a→n`,
      `In embedding space, the triplet loss gradient pulls the anchor toward the positive and pushes it away from the negative. The margin creates a "forbidden zone" — negatives must be at least margin farther than positives. Hard negative mining (selecting negatives that are close to the anchor but from a different class) is critical for effective training, as easy negatives contribute zero gradient.`,
      'step-space', C.header.stroke, C.header.fill,
      [`# Gradient when L > 0:`, `# dL/da = 2*(a-p)/||a-p|| - 2*(a-n)/||a-n||`, `# dL/dp = -2*(a-p)/||a-p||`, `# dL/dn = 2*(a-n)/||a-n||`, `# Hard negative mining: select n with smallest d(a,n)`]));
  }

  return { steps, y };
}

// ── Main entry point ─────────────────────────────────────────────────

export function renderContrastiveLossDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const d = Math.max(2, Math.min(Number(params.d_model) || 512, 4096));
  const N = Math.max(2, Math.min(Number(params.batch_size) || 64, 1024));
  const tau = Number(params.temperature) || 0.07;
  const variant = String(params.variant || 'infonce') as CLVariant;

  const stepsMeta: CLStep[] = [];
  let y = 10;

  lbl(g, CX, y + 14, 'Contrastive Loss', { size: 18, weight: '700', color: 'var(--text)' });
  const subtitle = variant === 'infonce'
    ? 'InfoNCE — in-batch negative contrastive learning (CLIP, text embeddings)'
    : variant === 'nt-xent'
    ? 'NT-Xent — symmetric contrastive loss (SimCLR)'
    : 'Triplet Loss — anchor/positive/negative with margin';
  lbl(g, CX, y + 36, subtitle, { size: 11, color: C.muted });
  y += 56;

  const { steps, y: finalY } = variant === 'nt-xent'
    ? renderNTXent(g, y, N, d, tau)
    : variant === 'triplet'
    ? renderTriplet(g, y, N, d)
    : renderInfoNCE(g, y, N, d, tau);
  stepsMeta.push(...steps);
  y = finalY;

  const insightText = variant === 'triplet'
    ? `Triplet loss explicitly pulls anchor-positive pairs together and pushes anchor-negative pairs apart using a margin-based hinge function. L = max(0, d(a,p) − d(a,n) + m). The margin m ensures a minimum separation. Hard negative mining is critical — easy negatives (already far) contribute zero gradient.`
    : variant === 'nt-xent'
    ? `NT-Xent (Normalized Temperature-scaled Cross Entropy) is the symmetric variant used in SimCLR. It computes the contrastive loss in both directions (i→j and j→i), providing 2N gradient signals per batch. The temperature τ controls the sharpness of the similarity distribution.`
    : `InfoNCE treats contrastive learning as a classification problem: given an anchor, identify the positive from N−1 in-batch negatives. L = −log(exp(sim(a,p)/τ) / Σ exp(sim(a,n)/τ)). The batch itself provides negatives — no explicit negative sampling needed.`;

  const perfText = `Contrastive losses are O(N²) in batch size due to the similarity matrix, but benefit greatly from large batch sizes (more negatives = better learning). Memory: O(N×d) for embeddings + O(N²) for similarity matrix. Large batch (1024+) is ideal but requires careful memory management.`;

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'softmax', 'Softmax');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'cross-entropy', 'Cross-Entropy');
  y += 80;

  const codeLines = variant === 'triplet'
    ? [
      `# Triplet loss`,
      `a, p, n = F.normalize(a, dim=-1), F.normalize(p, dim=-1), F.normalize(n, dim=-1)`,
      `d_ap = (a - p).pow(2).sum(dim=-1).sqrt()`,
      `d_an = (a - n).pow(2).sum(dim=-1).sqrt()`,
      `loss = F.relu(d_ap - d_an + margin).mean()`,
      `# OR use torch.nn.TripletMarginLoss`,
      `loss = nn.TripletMarginLoss(margin=1.0)(a, p, n)`,
    ]
    : variant === 'nt-xent'
    ? [
      `# NT-Xent (SimCLR)`,
      `z_i = F.normalize(encoder(x_i), dim=-1)`,
      `z_j = F.normalize(encoder(x_j), dim=-1)`,
      `S = z_i @ z_j.T / tau  # [N, N]`,
      `loss_ij = F.cross_entropy(S, torch.arange(N))`,
      `loss_ji = F.cross_entropy(S.t(), torch.arange(N))`,
      `loss = (loss_ij + loss_ji) / 2`,
    ]
    : [
      `# InfoNCE`,
      `z_i = F.normalize(encoder(x_i), dim=-1)`,
      `z_j = F.normalize(encoder(x_j), dim=-1)`,
      `S = z_i @ z_j.T / tau  # [N, N]`,
      `loss = F.cross_entropy(S, torch.arange(N))`,
    ];

  y = drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160,
    `Contrastive Loss — ${variant === 'nt-xent' ? 'NT-Xent' : variant === 'triplet' ? 'Triplet' : 'InfoNCE'}`,
    [`variant: ${variant}`, `batch_size: ${N}`, `d_model: ${d}`, `temperature: ${tau}`],
    codeLines);

  return { width: W, height: y + FOOTER_PAD, steps: stepsMeta };
}
